//! Real proof verification tests using fixtures generated from V2 circom circuits.
//!
//! These tests verify that the Groth16 verifier correctly accepts proofs
//! generated by snarkjs with real circuit VKs and rejects proofs with
//! corrupted signals.

extern crate std;

use crate::groth16::verify_groth16;
use contract_types::{Groth16Proof, VerificationKeyBytes, SNARK_SCALAR_FIELD_BYTES};
use serde::Deserialize;
use soroban_sdk::{Bytes, BytesN, Env, Vec, U256};

// ─── Fixture Loading ──────────────────────────────────────────────────────

#[derive(Deserialize)]
struct VKFixture {
    alpha: std::string::String,
    beta: std::string::String,
    gamma: std::string::String,
    delta: std::string::String,
    ic: std::vec::Vec<std::string::String>,
}

#[derive(Deserialize)]
struct ProofFixture {
    a: std::string::String,
    b: std::string::String,
    c: std::string::String,
}

#[derive(Deserialize)]
struct Fixture {
    #[allow(dead_code)]
    circuit: std::string::String,
    vk: VKFixture,
    proof: ProofFixture,
    public_signals: std::vec::Vec<std::string::String>,
    #[allow(dead_code)]
    public_signals_decimal: std::vec::Vec<std::string::String>,
}

fn hex_to_bytes(hex: &str) -> std::vec::Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("valid hex"))
        .collect()
}

fn load_fixture(name: &str) -> Fixture {
    let path = std::format!(
        "{}/../../tests/fixtures/{}.json",
        env!("CARGO_MANIFEST_DIR"),
        name
    );
    let data = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("Failed to read fixture {}: {}", path, e));
    serde_json::from_str(&data).expect("valid fixture JSON")
}

fn fixture_to_vk(env: &Env, f: &VKFixture) -> VerificationKeyBytes {
    let alpha_bytes = hex_to_bytes(&f.alpha);
    let beta_bytes = hex_to_bytes(&f.beta);
    let gamma_bytes = hex_to_bytes(&f.gamma);
    let delta_bytes = hex_to_bytes(&f.delta);

    let mut ic_vec: Vec<BytesN<64>> = Vec::new(env);
    for ic_hex in &f.ic {
        let ic_bytes = hex_to_bytes(ic_hex);
        let arr: [u8; 64] = ic_bytes.try_into().expect("IC point must be 64 bytes");
        ic_vec.push_back(BytesN::from_array(env, &arr));
    }

    VerificationKeyBytes {
        alpha: BytesN::from_array(
            env,
            &<[u8; 64]>::try_from(alpha_bytes.as_slice()).expect("alpha 64 bytes"),
        ),
        beta: BytesN::from_array(
            env,
            &<[u8; 128]>::try_from(beta_bytes.as_slice()).expect("beta 128 bytes"),
        ),
        gamma: BytesN::from_array(
            env,
            &<[u8; 128]>::try_from(gamma_bytes.as_slice()).expect("gamma 128 bytes"),
        ),
        delta: BytesN::from_array(
            env,
            &<[u8; 128]>::try_from(delta_bytes.as_slice()).expect("delta 128 bytes"),
        ),
        ic: ic_vec,
    }
}

fn fixture_to_proof(env: &Env, f: &ProofFixture) -> Groth16Proof {
    let a_bytes = hex_to_bytes(&f.a);
    let b_bytes = hex_to_bytes(&f.b);
    let c_bytes = hex_to_bytes(&f.c);

    Groth16Proof {
        a: BytesN::from_array(
            env,
            &<[u8; 64]>::try_from(a_bytes.as_slice()).expect("A 64 bytes"),
        ),
        b: BytesN::from_array(
            env,
            &<[u8; 128]>::try_from(b_bytes.as_slice()).expect("B 128 bytes"),
        ),
        c: BytesN::from_array(
            env,
            &<[u8; 64]>::try_from(c_bytes.as_slice()).expect("C 64 bytes"),
        ),
    }
}

fn fixture_to_signals(env: &Env, signals: &[std::string::String]) -> Vec<U256> {
    let mut result = Vec::new(env);
    for hex in signals {
        let bytes = hex_to_bytes(hex);
        let arr: [u8; 32] = bytes.try_into().expect("signal must be 32 bytes");
        result.push_back(U256::from_be_bytes(env, &Bytes::from_array(env, &arr)));
    }
    result
}

fn verify_fixture(name: &str) -> bool {
    let fixture = load_fixture(name);
    let env = Env::default();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);
    verify_groth16(&env, &vk, &proof, &signals)
}

/// Create an environment with unlimited budget for multi-verification tests.
fn env_unlimited() -> Env {
    let env = Env::default();
    env.budget().reset_unlimited();
    env
}

/// Corrupt a single signal by adding 1 (mod field).
fn corrupt_signal(env: &Env, signals: &Vec<U256>, index: u32) -> Vec<U256> {
    let mut result = Vec::new(env);
    for i in 0..signals.len() {
        let signal = signals.get(i).expect("signal");
        if i == index {
            // Add 1 to the signal bytes (simple corruption)
            let mut corrupted = [0u8; 32];
            signal.to_be_bytes().copy_into_slice(&mut corrupted);
            // Increment the last byte (handles simple cases)
            let last = corrupted[31];
            corrupted[31] = last.wrapping_add(1);
            result.push_back(U256::from_be_bytes(env, &Bytes::from_array(env, &corrupted)));
        } else {
            result.push_back(signal);
        }
    }
    result
}

// ─── Deposit Tests ────────────────────────────────────────────────────────

#[test]
fn test_real_deposit_proof_verifies() {
    assert!(verify_fixture("deposit"), "deposit proof should verify");
}

#[test]
fn test_real_deposit_corrupt_signal_0() {
    let fixture = load_fixture("deposit");
    let env = Env::default();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);
    let corrupted = corrupt_signal(&env, &signals, 0);
    assert!(
        !verify_groth16(&env, &vk, &proof, &corrupted),
        "deposit: corrupted signal 0 should fail"
    );
}

#[test]
fn test_real_deposit_corrupt_signal_1() {
    let fixture = load_fixture("deposit");
    let env = Env::default();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);
    let corrupted = corrupt_signal(&env, &signals, 1);
    assert!(
        !verify_groth16(&env, &vk, &proof, &corrupted),
        "deposit: corrupted signal 1 should fail"
    );
}

#[test]
fn test_real_deposit_corrupt_signal_2() {
    let fixture = load_fixture("deposit");
    let env = Env::default();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);
    let corrupted = corrupt_signal(&env, &signals, 2);
    assert!(
        !verify_groth16(&env, &vk, &proof, &corrupted),
        "deposit: corrupted signal 2 should fail"
    );
}

#[test]
fn test_real_deposit_wrong_vk() {
    // Use ragequit VK with deposit proof — should fail
    let deposit = load_fixture("deposit");
    let ragequit = load_fixture("ragequit");
    let env = Env::default();
    let wrong_vk = fixture_to_vk(&env, &ragequit.vk);
    let proof = fixture_to_proof(&env, &deposit.proof);
    let signals = fixture_to_signals(&env, &deposit.public_signals);
    // Wrong VK has different IC count, should return false (IC length mismatch)
    assert!(
        !verify_groth16(&env, &wrong_vk, &proof, &signals),
        "deposit: wrong VK should fail"
    );
}

// ─── Ragequit Tests ───────────────────────────────────────────────────────

#[test]
fn test_real_ragequit_proof_verifies() {
    assert!(verify_fixture("ragequit"), "ragequit proof should verify");
}

#[test]
fn test_real_ragequit_corrupt_each_signal() {
    let fixture = load_fixture("ragequit");
    let env = env_unlimited();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);

    // Ragequit has 7 public signals — corrupt each one
    for i in 0..signals.len() {
        let corrupted = corrupt_signal(&env, &signals, i);
        assert!(
            !verify_groth16(&env, &vk, &proof, &corrupted),
            "ragequit: corrupted signal {} should fail",
            i,
        );
    }
}

/// The field-aliasing double-spend. `Fr::from_u256` reduces mod r, so without a canonical check
/// a proof for signal `x` also verifies for `x + r` — and the pool keys nullifiers/commitments on
/// the RAW value, so each alias was a fresh, unspent nullifier (up to 6 spends per note). Every
/// signal of every circuit is lifted by `r` in turn; each lifted set must be rejected, while the
/// untouched set still verifies (so the rejection is the canonical check, not a broken fixture).
#[test]
fn test_real_proofs_reject_field_aliased_signals() {
    let env = env_unlimited();
    let r = U256::from_be_bytes(&env, &Bytes::from_slice(&env, &SNARK_SCALAR_FIELD_BYTES));
    for name in ["deposit", "ragequit", "transact_1x1", "transact_2x2"] {
        let fixture = load_fixture(name);
        let vk = fixture_to_vk(&env, &fixture.vk);
        let proof = fixture_to_proof(&env, &fixture.proof);
        let signals = fixture_to_signals(&env, &fixture.public_signals);
        assert!(verify_groth16(&env, &vk, &proof, &signals), "{name}: canonical signals must verify");
        for i in 0..signals.len() {
            let mut aliased = signals.clone();
            aliased.set(i, signals.get(i).expect("signal").add(&r));
            assert!(
                !verify_groth16(&env, &vk, &proof, &aliased),
                "{name}: signal {i} lifted by r must be rejected",
            );
        }
    }
}

// ─── Transact 1x1 Tests ──────────────────────────────────────────────────

#[test]
fn test_real_transact_1x1_proof_verifies() {
    assert!(
        verify_fixture("transact_1x1"),
        "transact_1x1 proof should verify"
    );
}

#[test]
fn test_real_transact_1x1_corrupt_each_signal() {
    let fixture = load_fixture("transact_1x1");
    let env = env_unlimited();
    let vk = fixture_to_vk(&env, &fixture.vk);
    let proof = fixture_to_proof(&env, &fixture.proof);
    let signals = fixture_to_signals(&env, &fixture.public_signals);

    // Transact 1x1 has 8 public signals — corrupt each one
    for i in 0..signals.len() {
        let corrupted = corrupt_signal(&env, &signals, i);
        assert!(
            !verify_groth16(&env, &vk, &proof, &corrupted),
            "transact_1x1: corrupted signal {} should fail",
            i,
        );
    }
}

// ─── Transact NxM Tests (all 25 configs) ──────────────────────────────────

macro_rules! transact_test {
    ($name:ident, $fixture:expr) => {
        #[test]
        fn $name() {
            assert!(verify_fixture($fixture), "{} proof should verify", $fixture,);
        }
    };
}

macro_rules! transact_corruption_test {
    ($name:ident, $fixture:expr) => {
        #[test]
        fn $name() {
            let fixture = load_fixture($fixture);
            let env = env_unlimited();
            let vk = fixture_to_vk(&env, &fixture.vk);
            let proof = fixture_to_proof(&env, &fixture.proof);
            let signals = fixture_to_signals(&env, &fixture.public_signals);

            for i in 0..signals.len() {
                let corrupted = corrupt_signal(&env, &signals, i);
                assert!(
                    !verify_groth16(&env, &vk, &proof, &corrupted),
                    "{}: corrupted signal {} should fail",
                    $fixture,
                    i,
                );
            }
        }
    };
}

// Happy path verification for all 25 NxM configs
transact_test!(test_real_transact_1x2, "transact_1x2");
transact_test!(test_real_transact_1x3, "transact_1x3");
transact_test!(test_real_transact_1x4, "transact_1x4");
